DROP TABLE IF EXISTS `api_credentials`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `api_credentials` (
  `credential_id` int(11) NOT NULL AUTO_INCREMENT,
  `service_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `public_key_id` varchar(20) DEFAULT NULL,
  `secret_hash` varchar(128) DEFAULT NULL,
  `key_last_four` char(4) DEFAULT NULL,
  `secret_key` varchar(64) DEFAULT NULL,
  `status` enum('active','paused','revoked') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `expires_at` datetime DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `revoked_at` datetime DEFAULT NULL,
  PRIMARY KEY (`credential_id`),
  UNIQUE KEY `uk_service_user` (`service_id`,`user_id`),
  KEY `idx_secret_key` (`secret_key`),
  KEY `idx_service_id` (`service_id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
